Rule.Source:
import java.util.Iterator;
import sailpoint.object.Certifiable;
import sailpoint.object.EntitlementGroup;
import sailpoint.object.Identity;

String explanation = null;

if (entity instanceof Identity) {
    Identity identity = (Identity) entity;
    if ("service".equalsIgnoreCase((String) identity.getAttribute("workerType"))) {
        itemsToExclude.addAll(items);
        items.clear();
        return "Service identity: reviewed in the service account campaign by its owner.";
    }
}

for (Iterator it = items.iterator(); it.hasNext();) {
    Certifiable c = (Certifiable) it.next();
    if (!(c instanceof EntitlementGroup)) {
        continue;
    }
    EntitlementGroup eg = (EntitlementGroup) c;
    if (eg.getApplication() == null || !FSGOV_FS_APP.equals(eg.getApplication().getName())) {
        continue;
    }
    Object groups = eg.getAttributes() == null ? null : eg.getAttributes().get("groups");
    boolean governed = false;
    for (Iterator g = fsgovAsList(groups).iterator(); g.hasNext();) {
        if (fsgovIsGovernedGroup(context, (String) g.next())) {
            governed = true;
        }
    }
    if (!governed && eg.getPermissions() == null) {
        itemsToExclude.add(c);
        it.remove();
        explanation = "Group outside the governed share catalog; tracked by the orphan report.";
    }
}
return explanation;
